const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let active=0,tab='Reagire';const $=id=>document.getElementById(id);
function renderTopics(){
 $('categories').innerHTML=['Tutte',...topicCategories].map(c=>`<button type="button" class="category-chip ${category===c?'selected':''}" data-category="${esc(c)}" aria-pressed="${category===c}">${esc(c)}</button>`).join('');
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;renderTopics()});
 $('topics').innerHTML=topics.map((t,i)=>category==='Tutte'||category===topicCategories[i]?`<button type="button" class="topic ${active===i?'active':''}" aria-pressed="${active===i}" data-id="${i}"><span class="symbol">${t.icon}</span><strong>${esc(t.title)}</strong></button>`:'').join('');
 document.querySelectorAll('.topic').forEach(b=>b.addEventListener('click',()=>{cleanAudio();active=Number(b.dataset.id);renderTopics();renderConversation();if(innerWidth<940)$('conversation').scrollIntoView({behavior:'smooth',block:'start'})}));
}
function grammar(items){return items.map(([title,ex])=>`<div class="grammar-item"><b>${esc(title)}</b><em>${esc(ex)}</em></div>`).join('')}
const sessionStorageKey='parliamo-session-v1';
let session={minutes:30,phase:'ready',remaining:1800,deadline:null,startedAt:null,elapsed:0,finished:false};
try{const v=JSON.parse(localStorage.getItem(sessionStorageKey)||'null');if(v&&[15,20,30].includes(v.minutes)&&['ready','running','paused','done'].includes(v.phase))session={...session,...v}}catch{}
function persistSession(){try{localStorage.setItem(sessionStorageKey,JSON.stringify(session))}catch{}}
function timeLeft(){return session.phase==='running'?Math.max(0,Math.ceil((session.deadline-Date.now())/1000)):Math.max(0,session.remaining)}
function timeText(secs){return String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')}
function countWords(value){const txt=value.trim();return txt?txt.split(/\s+/u).filter(Boolean).length:0}
function totalWords(){return [...document.querySelectorAll('[data-answer]')].reduce((a,t)=>a+countWords(t.value),0)}
function sessionMarkup(){return ''}
function markFinished(){if(session.phase!=='running')return;session.elapsed+=Math.max(0,(Date.now()-session.startedAt)/1000);session.phase='done';session.remaining=0;session.deadline=null;session.startedAt=null;session.finished=true;persistSession()}
function refreshSession(){if(session.phase==='running'&&timeLeft()===0)markFinished();const clock=$('sessionClock');if(!clock)return;clock.textContent=timeText(timeLeft());const label=$('timerStateLabel');if(label)label.textContent=({ready:'Inizia',running:'In corso',paused:'In pausa',done:'Conclusa'})[session.phase];const toggle=$('sessionToggle');if(toggle)toggle.textContent=({ready:'Inizia',running:'Pausa',paused:'Riprendi',done:'Nuova sessione'})[session.phase];const invite=$('sessionInvite');if(invite)invite.hidden=true;if(clock){clock.closest('.header-timer')?.classList.toggle('timer-needs-start',session.phase==='ready'||session.phase==='done')}const msg=$('sessionMessage');if(msg)msg.textContent=({ready:'Scegli 15, 20 o 30 minuti e inizia quando vuoi.',running:'Il timer continua anche cambiando pagina.',paused:'Tempo fermato. Riprendi quando vuoi.',done:'Sessione conclusa! Puoi continuare a praticare.'})[session.phase];document.querySelectorAll('[data-minutes]').forEach(btn=>{btn.setAttribute('aria-pressed',String(+btn.dataset.minutes===session.minutes));btn.disabled=session.phase==='running'||session.phase==='paused'});}
function resetSession(minutes=session.minutes){session={minutes,phase:'ready',remaining:minutes*60,deadline:null,startedAt:null,elapsed:0,finished:false};persistSession();refreshSession()}
function toggleSession(){if(session.phase==='ready'||session.phase==='done'){if(session.phase==='done')resetSession();session.phase='running';session.startedAt=Date.now();session.deadline=Date.now()+session.remaining*1000}else if(session.phase==='running'){session.remaining=timeLeft();session.elapsed+=Math.max(0,(Date.now()-session.startedAt)/1000);session.phase='paused';session.deadline=null;session.startedAt=null}else{session.phase='running';session.startedAt=Date.now();session.deadline=Date.now()+session.remaining*1000}persistSession();refreshSession()}
function setupSessionUI(){document.querySelectorAll('[data-minutes]').forEach(b=>b.onclick=()=>resetSession(Number(b.dataset.minutes)));const t=$('sessionToggle'),r=$('sessionReset');if(t)t.onclick=toggleSession;if(r)r.onclick=()=>resetSession();const p=$('timerPanel'),btn=$('timerPanelToggle');function openPanel(){if(p&&btn){p.hidden=false;btn.setAttribute('aria-expanded','true')}}if(btn&&p){btn.onclick=()=>{p.hidden=!p.hidden;btn.setAttribute('aria-expanded',String(!p.hidden))};document.addEventListener('click',e=>{if(!p.hidden&&!e.target.closest('.header-timer')&&!e.target.closest('#sessionInviteOptions')){p.hidden=true;btn.setAttribute('aria-expanded','false')}})}const modal=$('startModal'),go=$('startModalGo'),skip=$('startModalSkip');let chosen=session.minutes;const buttons=[...document.querySelectorAll('[data-start-duration]')];function selectDuration(n){chosen=n;buttons.forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.startDuration===n)))}selectDuration(chosen);buttons.forEach(b=>b.onclick=()=>selectDuration(+b.dataset.startDuration));function dismissModal(){if(modal)modal.hidden=true;try{sessionStorage.setItem('parliamo-start-prompt-dismissed','1')}catch{}}if(go)go.onclick=()=>{resetSession(chosen);toggleSession();dismissModal()};if(skip)skip.onclick=dismissModal;try{if(modal&&document.body.dataset.page!=='help'&&(session.phase==='ready'||session.phase==='done')&&!sessionStorage.getItem('parliamo-start-prompt-dismissed')){modal.hidden=false;setTimeout(()=>go?.focus(),0)}}catch{};const start=$('sessionQuickStart'),opts=$('sessionInviteOptions');if(start)start.onclick=()=>{if(session.phase==='ready'||session.phase==='done')toggleSession();else if(session.phase==='paused')toggleSession();openPanel();if(p){p.hidden=true;btn.setAttribute('aria-expanded','false')}};if(opts)opts.onclick=openPanel;refreshSession()}
function updateWritingMetrics(){document.querySelectorAll('[data-answer]').forEach((field,i)=>{const count=countWords(field.value);const target=i===1?35:25;const countEl=$('response-count-'+i),hint=$('response-hint-'+i),bar=$('response-fill-'+i);if(!countEl)return;countEl.textContent=count+' '+(count===1?'parola':'parole');hint.textContent=count===0?'Prova a comunicare il tuo messaggio.':count<12?'Aggiungi un esempio o un dettaglio.':count<target?'Bene! Puoi dire qualcosa in più?':'Hai sviluppato la risposta!';bar.style.width=Math.min(100,100*count/target)+'%'});refreshSession()}
setInterval(()=>{if(session.phase==='running'&&timeLeft()===0){markFinished()}refreshSession()},1000);


