function setupContinuations(){document.querySelectorAll('[data-continue]').forEach(button=>{const i=Number(button.dataset.continue),questions=continuationBank[active*4+i]||[];let index=-1;const output=document.getElementById('continue-question-'+i);button.addEventListener('click',()=>{if(index>=questions.length-1)return;index++;output.hidden=false;output.replaceChildren();const count=document.createElement('small');count.textContent='DOMANDA '+(index+1)+' DI '+questions.length;const question=document.createElement('p');question.textContent=questions[index];output.append(count,question);if(index===questions.length-1){button.textContent='Hai visto tutti gli spunti';button.disabled=true;}else{button.textContent='Un’altra domanda →';}});});}

function renderConversation(){let t=topics[active];$('conversation').innerHTML=`<div class="kicker">Conversazione ${active+1} / 5</div><h2>${esc(t.title)}</h2><p class="scenario">${esc(t.scenario)}</p><div class="starter"><label>PER COMINCIARE</label><p>“${esc(t.starter)}”</p></div>${sessionMarkup()}<div class="sectiontitle">🗣️ Svolgi questi compiti</div><p class="help">Ogni tappa è un atto comunicativo. Scrivi ciò che diresti al tuo parente; puoi scegliere l’ordine dei compiti.</p><div class="questions-path">${t.questions.map((q,i)=>`<div class="question-step"><div class="path-marker"><span>${i+1}</span></div><div class="question-content"><span class="act-label">${esc(stageLabels[active][i])}</span><label for="answer-${i}" class="question-text">${esc(q)}</label><button type="button" class="act-grammar" data-act-grammar="${grammarForAct[active][i]}" title="Apri la grammatica utile per questa domanda">◈ ${grammarShort[grammarForAct[active][i]]}</button><textarea class="answer-field" id="answer-${i}" data-answer="${i}" rows="3" placeholder="Scrivi qui la tua risposta..."></textarea><div class="response-feedback"><span id="response-count-${i}">0 parole</span><span id="response-hint-${i}">Comincia con una frase.</span></div><div class="response-track" aria-hidden="true"><div class="response-fill" id="response-fill-${i}" style="width:0%"></div></div><div class="continuation" data-continuation="${i}"><button class="continue-button" type="button" data-continue="${i}" aria-controls="continue-question-${i}">✧ Aiutami a continuare</button><div class="continue-question" id="continue-question-${i}" aria-live="polite" hidden></div></div></div></div>`).join('')}</div><div class="answer-actions"><span class="hint" id="textstatus" role="status">Risposte salvate automaticamente sul dispositivo</span><div class="action-line"><button class="btn secondary" id="copytext" type="button">Copia le risposte</button><button class="btn secondary" id="downloadtext" type="button">Scarica .txt</button></div></div><details class="accordion"><summary>📖 Glossario italiano–olandese</summary><div class="accbody"><table class="lex-table"><thead><tr><th>Tipo</th><th>Italiano</th><th>Nederlands</th><th>Salva</th></tr></thead><tbody>${t.lex.map((r,i)=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}<td><button type="button" class="lex-add" data-lex="${i}" aria-label="Aggiungi al quaderno: ${esc(r[1])}">＋</button></td></tr>`).join('')}</tbody></table></div></details><details class="accordion"><summary>🧩 Grammatica utile</summary><div class="accbody"><div class="sectiontitle">Mi serve per parlare</div>${grammar(t.essential)}<div class="sectiontitle">Posso dire anche...</div>${grammar(t.optional)}<p class="help">Puoi usare le strutture che conosci già: non devi impararle tutte prima di parlare.</p></div></details><section class="recording"><h3>🎙️ Prova a raccontarlo a voce</h3><p class="help">Registra la tua voce, riascoltala e, se vuoi, salva il file audio. Serve il permesso per usare il microfono.</p><div class="rec-buttons"><button class="btn" id="recordStart" type="button">● Registra</button><button class="btn secondary" id="recordStop" type="button" disabled>■ Ferma</button><button class="btn secondary" id="recordDownload" type="button" disabled>↓ Salva audio</button></div><div class="rec-status" id="recStatus" role="status">Pronto per registrare.</div><audio id="recordPlayback" controls hidden></audio><p class="side-note">Per registrare serve un browser compatibile e l'accesso al microfono (HTTPS o localhost). Scarica l'audio per conservarlo.</p></section>`;setupPractice();setupContinuations();document.querySelectorAll('[data-act-grammar]').forEach(b=>b.addEventListener('click',()=>openTool('grammar',b.dataset.actGrammar)));document.querySelectorAll('[data-lex]').forEach(b=>b.addEventListener('click',()=>{const r=topics[active].lex[Number(b.dataset.lex)];addWord(r[1],r[2]);b.textContent='✓';$('status').textContent='Aggiunta dal glossario: '+r[1]}))}

const notesKey='italiano-famiglia-testi-v2';let notes={};try{notes=JSON.parse(localStorage.getItem(notesKey)||'{}')||{}}catch{notes={}}
function saveFile(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
let recorder=null,stream=null,recordParts=[],audioUrl=null,recordBlob=null,recordTopic=null;
function cleanAudio(){if(recorder&&recorder.state==='recording')recorder.stop();if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}if(audioUrl){URL.revokeObjectURL(audioUrl);audioUrl=null}recordBlob=null;recorder=null}
function setupPractice(){const fields=[...document.querySelectorAll('[data-answer]')];const legacy=typeof notes[active]==='string'?notes[active]:'';const stored=Array.isArray(notes[active])?notes[active]:[];fields.forEach((ta,i)=>{ta.value=stored[i]||(i===0?legacy:'');ta.addEventListener('input',()=>{notes[active]=fields.map(f=>f.value);try{localStorage.setItem(notesKey,JSON.stringify(notes));$('textstatus').textContent='Risposte salvate automaticamente.';updateWritingMetrics()}catch{$('textstatus').textContent='Salvataggio non disponibile: copia o scarica le risposte.'}})});updateWritingMetrics();const allAnswers=()=>fields.map((ta,i)=>stageLabels[active][i]+' — '+topics[active].questions[i]+'\n'+ta.value).join('\n\n');$('copytext').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(allAnswers());$('textstatus').textContent='Risposte copiate.'}catch{$('textstatus').textContent='Copia non disponibile: usa Scarica .txt.'}});$('downloadtext').addEventListener('click',()=>saveFile('conversazione-'+(active+1)+'.txt',new Blob([allAnswers()],{type:'text/plain;charset=utf-8'})));cleanAudio();const start=$('recordStart'),stop=$('recordStop'),down=$('recordDownload'),stat=$('recStatus'),player=$('recordPlayback');const supported=!!(navigator.mediaDevices?.getUserMedia&&window.MediaRecorder);if(!supported){start.disabled=true;stat.textContent=(location.protocol==='file:'?'Il file è aperto direttamente dal computer: questo browser può bloccare il microfono per motivi di sicurezza. Pubblica la pagina su HTTPS oppure aprila da localhost.':'Il microfono non è accessibile in questo contesto. Verifica HTTPS, permessi del sito e disponibilità del dispositivo.');return}start.onclick=async()=>{start.disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);recordParts=[];recordBlob=null;recordTopic=active;down.disabled=true;player.hidden=true;recorder.ondataavailable=e=>{if(e.data.size)recordParts.push(e.data)};recorder.onstop=()=>{const type=recorder.mimeType||'audio/webm';recordBlob=new Blob(recordParts,{type});if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(recordBlob);player.src=audioUrl;player.hidden=false;down.disabled=false;stop.disabled=true;start.disabled=false;stat.textContent='Registrazione pronta: puoi ascoltarla o salvarla.';stream?.getTracks().forEach(t=>t.stop());stream=null};recorder.start();stop.disabled=false;stat.innerHTML='<span class="live"><span class="rec-dot"></span>Registrazione in corso...</span>'}catch(e){start.disabled=false;const msg={NotAllowedError:'Accesso al microfono negato: autorizzalo dalle impostazioni del sito nel browser.',NotFoundError:'Nessun microfono rilevato: collega un microfono o verifica l’ingresso audio del computer.',NotReadableError:'Il microfono è occupato o non è accessibile: chiudi le altre app che lo usano.',SecurityError:'Per motivi di sicurezza il microfono è bloccato. Apri la pagina tramite HTTPS o localhost.'};stat.textContent=msg[e.name]||('Non è stato possibile avviare la registrazione ('+e.name+'). Verifica il microfono e i permessi.');stream?.getTracks().forEach(t=>t.stop());stream=null}};stop.onclick=()=>{if(recorder?.state==='recording'){stop.disabled=true;recorder.stop()}};down.onclick=()=>{if(recordBlob){let ext=recordBlob.type.includes('mp4')?'m4a':recordBlob.type.includes('ogg')?'ogg':'webm';saveFile('conversazione-'+(recordTopic+1)+'.'+ext,recordBlob)}}}

function expressionCards(items,featured=false){return `<div class="${featured?'connective-grid':'chunklist'}">${items.map(([it,nl],i)=>`<div class="expr-card"><div><strong>${esc(it)}</strong><small>${esc(nl)}</small></div><button type="button" class="lex-add" data-expression="${esc(it)}" data-translation="${esc(nl)}" title="Aggiungi al quaderno" aria-label="Salva ${esc(it)} nel quaderno">＋</button></div>`).join('')}</div>`}
function connectiveFeature(){return `<section class="connective-feature"><h3>↗ Connettivi per continuare a parlare</h3><p>Collega due idee, racconta in ordine o spiega un motivo. Premi ＋ per salvare un'espressione nel quaderno.</p>${expressionCards(chunks.Connettivi,true)}</section>`}
function wireExpressionButtons(root){root.querySelectorAll('[data-expression]').forEach(btn=>btn.addEventListener('click',()=>{addWord(btn.dataset.expression,btn.dataset.translation);btn.textContent='✓';btn.closest('.expr-card')?.classList.add('is-saved');btn.title='Aggiunto al quaderno'}))}
function renderChunks(){$('tabs').innerHTML=Object.keys(chunks).filter(k=>k!=='Connettivi').map(k=>`<button type="button" class="tab ${tab===k?'active':''}" data-tab="${esc(k)}">${{PrendereTempo:'Prendere tempo'}[k]||k}</button>`).join('');document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;renderChunks()}));$('chunklist').innerHTML=(tab==='Connettivi'?'<p class="help">Seleziona una categoria per le altre espressioni.</p>':expressionCards(chunks[tab]));wireExpressionButtons($('chunklist'))}

const key='italiano-famiglia-vocaboli-v1';let words=[];try{const raw=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(raw))words=raw.filter(x=>Array.isArray(x)&&x.length===2&&x.every(v=>typeof v==='string'))}catch{}function persist(){try{localStorage.setItem(key,JSON.stringify(words));return true}catch{return false}}
function renderWords(){if($('wordcount'))$('wordcount').textContent=words.length;$('wordlist').innerHTML=words.length?`<table class="saved"><thead><tr><th>Italiano</th><th>Nederlands</th><th></th></tr></thead><tbody>${words.map(([it,nl],i)=>`<tr><td>${esc(it)}</td><td>${esc(nl)}</td><td><button class="mini" aria-label="Elimina parola ${esc(it)}" data-remove="${i}">×</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Non hai ancora aggiunto parole.</div>';document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{words.splice(Number(b.dataset.remove),1);persist();renderWords();$('status').textContent='Parola eliminata.'}))}
function addWord(it,nl){it=it.trim().replace(/[\t\r\n]+/g,' ');nl=nl.trim().replace(/[\t\r\n]+/g,' ');if(!it||!nl){$('status').textContent='Inserisci sia la parola italiana sia la traduzione olandese.';return false}words.push([it,nl]);const saved=persist();renderWords();$('status').textContent=saved?'✓ Parola aggiunta e salvata: '+it:'✓ Parola aggiunta: '+it+'. Salvataggio permanente non disponibile qui; scarica il TSV prima di chiudere la pagina.';return true} $('wordform').addEventListener('submit',e=>{e.preventDefault();if(addWord($('italian').value,$('dutch').value)){$('wordform').reset();$('italian').focus()}});const tsv=()=>words.map(([a,b])=>`${a.replace(/[\t\r\n]/g,' ')}\t${b.replace(/[\t\r\n]/g,' ')}`).join('\n');$('copy').addEventListener('click',async()=>{if(!words.length){$('status').textContent='Aggiungi almeno una parola.';return}try{await navigator.clipboard.writeText(tsv());$('status').textContent='Copiato! Incolla in Quizlet, Excel o Google Sheets.'}catch{const t=document.createElement('textarea');t.value=tsv();document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();$('status').textContent=ok?'Copiato negli appunti.':'Copia non disponibile: usa Scarica .tsv.'}});$('download').addEventListener('click',()=>{if(!words.length){$('status').textContent='Aggiungi almeno una parola.';return}const blob=new Blob(['\ufeff'+tsv()],{type:'text/tab-separated-values;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='parole-italiano-famiglia.tsv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='File TSV preparato.'});$('clear').addEventListener('click',()=>{if(!words.length)return;if(confirm('Vuoi eliminare tutte le parole salvate?')){words=[];persist();renderWords();$('status').textContent='Quaderno svuotato.'}});const drawer=$('notebookDrawer'),backdrop=$('drawerBackdrop');let previousFocus=null;function openDrawer(){previousFocus=document.activeElement;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');backdrop.hidden=false;document.body.classList.add('drawer-open');$('closeNotebook').focus()}function closeDrawer(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');backdrop.hidden=true;document.body.classList.remove('drawer-open');previousFocus?.focus()}$('openNotebook').onclick=openDrawer;$('openNotebookSide').onclick=openDrawer;$('closeNotebook').onclick=closeDrawer;backdrop.onclick=closeDrawer;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('open'))closeDrawer();if(e.key==='Tab'&&drawer.classList.contains('open')){const focusable=[...drawer.querySelectorAll('button,input')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus()}}});
const pronouns=['io','tu','lui / lei','noi','voi','loro'];
const regular={parlare:['parlo','parli','parla','parliamo','parlate','parlano'],prendere:['prendo','prendi','prende','prendiamo','prendete','prendono'],dormire:['dormo','dormi','dorme','dormiamo','dormite','dormono'],capire:['capisco','capisci','capisce','capiamo','capite','capiscono']};
const irregular={essere:['sono','sei','è','siamo','siete','sono'],avere:['ho','hai','ha','abbiamo','avete','hanno'],andare:['vado','vai','va','andiamo','andate','vanno'],fare:['faccio','fai','fa','facciamo','fate','fanno'],stare:['sto','stai','sta','stiamo','state','stanno'],volere:['voglio','vuoi','vuole','vogliamo','volete','vogliono'],potere:['posso','puoi','può','possiamo','potete','possono'],dovere:['devo','devi','deve','dobbiamo','dovete','devono'],dire:['dico','dici','dice','diciamo','dite','dicono'],venire:['vengo','vieni','viene','veniamo','venite','vengono']};
function conjugations(data){const names=Object.keys(data);return `<div class="grammar-scroll"><table class="grammar-table"><thead><tr><th>Persona</th>${names.map(v=>`<th>${esc(v)}</th>`).join('')}</tr></thead><tbody>${pronouns.map((pro,i)=>`<tr><td>${esc(pro)}</td>${names.map(v=>`<td>${esc(data[v][i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
const grammarSections=[
{id:'regolari',title:'1. Presente: verbi regolari',html:`<div class="rule">Parti dall'infinito, togli <b>-are / -ere / -ire</b> e aggiungi la desinenza della persona.</div>${conjugations(regular)}<p class="grammar-note">Il verbo <b>capire</b> aggiunge <b>-isc-</b> con io, tu, lui/lei e loro. Non tutti i verbi in -ire lo fanno.</p><span class="example">Con mia sorella <strong>parlo</strong> spesso; la sera <strong>prendiamo</strong> un caffè.</span>`},
{id:'irregolari',title:'2. Presente: verbi irregolari più usati',html:`<div class="rule">Questi verbi non seguono sempre lo schema regolare. Impara soprattutto le forme che usi quando parli di te e della tua famiglia.</div>${conjugations(Object.fromEntries(Object.entries(irregular).slice(0,5)))}${conjugations(Object.fromEntries(Object.entries(irregular).slice(5)))}<span class="example">Io <strong>vado</strong> in Italia, voi <strong>venite</strong> con noi? Mia zia <strong>vuole</strong> organizzare una cena.</span>`},
{id:'passato',title:'3. Passato prossimo',html:`<div class="mini-formula"><span>avere / essere al presente</span><b>＋</b><span>participio passato</span></div><div class="rule">Con <b>avere</b>: ho parlato, hai mangiato, abbiamo visto. Con molti verbi di movimento e cambiamento, come <b>andare, arrivare, partire, tornare</b>, si usa <b>essere</b>: sono andato/a, siamo arrivati/e.</div><table class="grammar-table"><thead><tr><th>Persona</th><th>avere + parlato</th><th>essere + andato/a</th></tr></thead><tbody>${pronouns.map((p,i)=>`<tr><td>${esc(p)}</td><td>${esc(irregular.avere[i])} parlato</td><td>${['sono andato/a','sei andato/a','è andato/a','siamo andati/e','siete andati/e','sono andati/e'][i]}</td></tr>`).join('')}</tbody></table><p class="grammar-note">Con <b>essere</b>, il participio cambia secondo genere e numero: Maria è arrivat<b>a</b>, Marco è arrivat<b>o</b>, loro sono arrivat<b>i/e</b>.</p><table class="grammar-table"><thead><tr><th>Infinito</th><th>Participio</th><th>Esempio</th></tr></thead><tbody>${[['fare','fatto','ho fatto'],['dire','detto','ho detto'],['vedere','visto','ho visto'],['prendere','preso','ho preso'],['scrivere','scritto','ho scritto'],['leggere','letto','ho letto'],['mettere','messo','ho messo'],['essere','stato','sono stato/a'],['venire','venuto','sono venuto/a']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`},
{id:'possessivi',title:'4. Possessivi: mio, tua, nostri...',html:`<div class="rule">Il possessivo concorda con la <b>cosa o persona posseduta</b>, non con chi possiede: <b>il mio</b> fratello, <b>la mia</b> sorella, <b>i miei</b> cugini, <b>le mie</b> zie.</div><table class="grammar-table"><thead><tr><th>Di chi?</th><th>masch. sing.</th><th>femm. sing.</th><th>masch. plur.</th><th>femm. plur.</th></tr></thead><tbody>${[['io','mio','mia','miei','mie'],['tu','tuo','tua','tuoi','tue'],['lui / lei','suo','sua','suoi','sue'],['noi','nostro','nostra','nostri','nostre'],['voi','vostro','vostra','vostri','vostre'],['loro','loro','loro','loro','loro']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="grammar-note">In genere usiamo l'articolo: <b>il mio</b> lavoro, <b>la nostra</b> casa. Con un familiare singolare spesso non lo usiamo: <b>mia madre, tuo fratello, nostra zia</b>. Ma: <b>i miei genitori</b>, <b>la mia sorellina</b>, <b>il loro padre</b>.</p>`},
{id:'concordanza',title:'5. Concordanza: sostantivi e aggettivi',html:`<div class="rule">L'aggettivo segue il <b>genere</b> e il <b>numero</b> del sostantivo. Le parole in <b>-e</b> possono essere sia maschili sia femminili: l'articolo aiuta a riconoscerle.</div><table class="grammar-table"><thead><tr><th></th><th>Singolare</th><th>Plurale</th></tr></thead><tbody><tr><td>Maschile -o</td><td>un cugino italiano</td><td>due cugini italiani</td></tr><tr><td>Femminile -a</td><td>una cugina italiana</td><td>due cugine italiane</td></tr><tr><td>Maschile -e</td><td>un parente gentile</td><td>due parenti gentili</td></tr><tr><td>Femminile -e</td><td>una madre felice</td><td>due madri felici</td></tr></tbody></table><div class="mini-formula"><span>parente → parenti</span><b>e</b><span>gentile → gentili</span></div><p class="grammar-note"><b>Attenzione:</b> per i sostantivi in -e il plurale è di solito in <b>-i</b>, sia maschile sia femminile: <b>il padre → i padri</b>; <b>la madre → le madri</b>. Gli aggettivi in -e usano <b>-e</b> al singolare e <b>-i</b> al plurale: un ragazzo <b>gentile</b>, una ragazza <b>gentile</b>, ragazzi e ragazze <b>gentili</b>.</p>`}
];
const grammarTips={
 regolari:'<b>Trucco:</b> per parlare di te basta partire da <b>io</b>; per parlare con un parente usa spesso <b>tu</b>. Non devi memorizzare tutte le persone nello stesso momento.',
 irregolari:'<b>Parti da 5 forme:</b> <b>sono, ho, vado, faccio, voglio</b>. Ti permettono già di raccontare molto della tua vita.',
 passato:'<b>Scorciatoia:</b> in molti racconti userai <b>avere</b> (ho mangiato, ho visto, abbiamo parlato). Impara come gruppetto a parte <b>andare, venire, arrivare, partire, tornare</b> con <b>essere</b>. Non esiste una percentuale semplice e universale valida per tutti i verbi.',
 possessivi:'<b>Guarda il familiare, non chi parla:</b> <b>mio</b> fratello, <b>mia</b> sorella, <b>i miei</b> cugini. Impara queste tre combinazioni come blocchi.',
 concordanza:'<b>Trucco per -e:</b> al singolare <b>gentile</b> resta uguale per lui e lei; al plurale diventa <b>gentili</b>. Per <b>parente</b> e <b>madre</b>, controlla prima l’articolo.'
};
