const grammarForAct=[['irregolari','passato','irregolari','regolari'],['irregolari','regolari','possessivi','irregolari'],['passato','possessivi','irregolari','concordanza'],['regolari','irregolari','passato','concordanza'],['irregolari','regolari','concordanza','irregolari']];
