let cefrLevel='A1.2',cefrMode='use';
function activateGrammar(root,id){if(!root)return;root.querySelectorAll('.grammar-chip[data-grammar-choice]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.grammarChoice===id)));let target=root.querySelector('[data-grammar-panel]');let item=grammarSections.find(g=>g.id===id)||grammarSections[0];if(target)target.innerHTML=`<article class="grammar-tile"><h3>${esc(item.title.replace(/^\d+\.\s*/,''))}</h3><div class="memory-tip">💡 ${grammarTips[item.id]}</div>${item.html}</article>`;}
function cefrView(root){const target=root.querySelector('[data-cefr-content]');if(!target)return;root.querySelectorAll('[data-cefr-level]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cefrLevel===cefrLevel)));root.querySelectorAll('[data-cefr-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cefrMode===cefrMode)));const entries=cefrSyllabus[cefrLevel][cefrMode];target.innerHTML=`<div class="cefr-caption"><span class="cefr-current">${esc(cefrLevel)} · ${cefrMode==='use'?'Utilizzare':'Riconoscere'}</span><br>${cefrMode==='use'?'Strutture da saper usare nelle proprie frasi.':'Strutture da capire quando le incontri in una conversazione.'} Questa è la progressione adottata dall’istituto.</div><div class="cefr-list">${entries.map(v=>`<div class="cefr-unit"><strong>${esc(v)}</strong>${cefrExamples[v]?`<small>${esc(cefrExamples[v])}</small>`:''}${cefrDetail[v]?`<button type="button" class="grammar-chip" data-grammar-detail="${cefrDetail[v]}">Apri spiegazione e forme →</button>`:''}</div>`).join('')}</div><div class="cefr-cardbox" data-grammar-panel></div>`;target.querySelectorAll('[data-grammar-detail]').forEach(b=>b.addEventListener('click',()=>{activateGrammar(root,b.dataset.grammarDetail);target.querySelector('[data-grammar-panel]')?.scrollIntoView({behavior:'smooth',block:'nearest'})}));}
function wireGrammar(root){root.querySelectorAll('[data-cefr-level]').forEach(b=>b.addEventListener('click',()=>{cefrLevel=b.dataset.cefrLevel;cefrView(root)}));root.querySelectorAll('[data-cefr-mode]').forEach(b=>b.addEventListener('click',()=>{cefrMode=b.dataset.cefrMode;cefrView(root)}));root.querySelectorAll('.grammar-chip[data-grammar-choice]').forEach(b=>b.addEventListener('click',()=>activateGrammar(root,b.dataset.grammarChoice)));}
function grammarVisual(){return `<div class="cefr-panel"><p class="help">Livelli della tabella ERK del tuo istituto. Seleziona il livello e ciò che vuoi praticare.</p><div class="cefr-levels" aria-label="Livello ERK">${cefrOrder.map(v=>`<button type="button" class="cefr-level" data-cefr-level="${v}" aria-pressed="${v===cefrLevel}">${v}</button>`).join('')}</div><div class="cefr-mode" aria-label="Tipo di competenza"><button type="button" data-cefr-mode="use" aria-pressed="${cefrMode==='use'}">Utilizzare</button><button type="button" data-cefr-mode="recognise" aria-pressed="${cefrMode==='recognise'}">Riconoscere</button></div><div data-cefr-content></div></div>`}
function renderGrammarOverview(){$('grammarOverview').innerHTML=grammarVisual();wireGrammar($('grammarOverview'));cefrView($('grammarOverview'))}

const toolDrawer=$('toolDrawer'),toolBackdrop=$('toolBackdrop');let toolPreviousFocus=null;
function toolHtml(type){let t=topics[active];if(type==='glossary')return `<p class="help">Vocabolario della conversazione: <b>${esc(t.title)}</b></p><table class="lex-table"><thead><tr><th>Tipo</th><th>Italiano</th><th>Nederlands</th><th>＋</th></tr></thead><tbody>${t.lex.map((r,i)=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}<td><button class="lex-add" type="button" data-tool-lex="${i}" aria-label="Salva ${esc(r[1])}">＋</button></td></tr>`).join('')}</tbody></table>`;if(type==='expressions')return connectiveFeature()+Object.entries(chunks).filter(([name])=>name!=='Connettivi').map(([name,items])=>`<h3>${esc(name==='PrendereTempo'?'Prendere tempo':name)}</h3>${expressionCards(items)}`).join('');return `<p class="help">Scegli un argomento. Comincia dal trucco, poi guarda la tabella solo se ti serve.</p><div class="grammar-overview">${grammarVisual()}</div><details class="accordion"><summary>Grammatica di questa conversazione</summary><div class="accbody"><h3>Mi serve per parlare</h3>${grammar(t.essential)}<h3>Posso dire anche</h3>${grammar(t.optional)}</div></details>`}

function openTool(type,selectedGrammar){if(drawer.classList.contains('open'))closeDrawer();toolPreviousFocus=document.activeElement;const names={glossary:'Glossario della conversazione',expressions:'Espressioni e connettivi',grammar:'Grammatica utile'};$('toolTitle').textContent=names[type]||'Strumenti';$('toolKicker').textContent=topics[active].title;$('toolContent').innerHTML=toolHtml(type);toolDrawer.classList.add('open');toolDrawer.setAttribute('aria-hidden','false');toolBackdrop.hidden=false;document.body.classList.add('drawer-open');$('closeTool').focus();wireExpressionButtons(toolDrawer);wireGrammar(toolDrawer);cefrView(toolDrawer);if(selectedGrammar){const area=toolDrawer.querySelector('[data-cefr-content]');if(area){area.querySelector('[data-grammar-panel]')?.scrollIntoView({block:'nearest'});activateGrammar(toolDrawer,selectedGrammar)}}toolDrawer.querySelectorAll('[data-grammar-link]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();toolDrawer.querySelector('#'+a.dataset.grammarLink)?.scrollIntoView({behavior:'smooth',block:'start'})}));toolDrawer.querySelectorAll('[data-tool-lex]').forEach(b=>b.onclick=()=>{const r=topics[active].lex[Number(b.dataset.toolLex)];addWord(r[1],r[2]);b.textContent='✓';b.title='Aggiunto al quaderno'})}
function closeTool(){toolDrawer.classList.remove('open');toolDrawer.setAttribute('aria-hidden','true');toolBackdrop.hidden=true;document.body.classList.remove('drawer-open');toolPreviousFocus?.focus()}
$('closeTool').onclick=closeTool;toolBackdrop.onclick=closeTool;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));
