function refreshImageText(){const n=countWords($('imageAnswer').value),target=$('imageLevel').value==='A1'?25:$('imageLevel').value==='A2'?55:85;$('imageWordCount').textContent=n+' '+(n===1?'parola':'parole');$('imageProgress').style.width=Math.min(100,100*n/target)+'%';$('imageHint').textContent=n===0?'Comincia da una cosa che vedi.':n<target*.35?'Aggiungi un luogo, una persona o un dettaglio.':n<target?'Ora collega la foto alla tua famiglia.':'Hai sviluppato bene la descrizione!'}
