(function(){const root=document.getElementById('acLibrary');if(!root)return;root.innerHTML='<div class="resource-heading"><div><div class="kicker">Catalogo degli atti comunicativi</div><h2>Che cosa vuoi dire?</h2><p>20 atti comunicativi dalle cinque conversazioni. Scegli il tema e salva i chunks nel quaderno.</p></div></div><div class="ac-controls"><select id="acTopic"><option value="">Tutte le conversazioni</option></select><input id="acSearch" class="field" placeholder="Cerca un atto comunicativo o un’espressione"></div><div class="ac-grid" id="acCards"></div>';const s=document.getElementById('acTopic'),q=document.getElementById('acSearch');[...new Set(acCatalog.map(x=>x.topic))].forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;s.appendChild(o)});function render(){const filtered=acCatalog.filter(x=>(!s.value||s.value===x.topic)&&(!q.value||(x.topic+' '+x.act+' '+x.chunks.map(c=>c.it+' '+c.nl).join(' ')).toLowerCase().includes(q.value.toLowerCase())));document.getElementById('acCards').innerHTML=filtered.map(x=>'<article class="ac-card"><div class="ac-category">'+esc(x.topic)+'</div><h3>'+esc(x.act)+'</h3>'+x.chunks.map(c=>'<div class="ac-chunk"><div><strong>'+esc(c.it)+'</strong><small>'+esc(c.nl)+'</small></div><button class="ac-save" data-it="'+esc(c.it)+'" data-nl="'+esc(c.nl)+'" title="Salva nel quaderno">＋</button></div>').join('')+'</article>').join('')||'<p>Nessuna espressione trovata.</p>';document.querySelectorAll('.ac-save').forEach(b=>b.onclick=()=>{addWord(b.dataset.it,b.dataset.nl);b.textContent='✓'})}s.onchange=render;q.oninput=render;render()})();
/* Refresh account data without reloading the page or interrupting audio. */
window.addEventListener('scrivimi:data-restored', () => {
  notes = JSON.parse(localStorage.getItem(notesKey) || '{}');
  words = JSON.parse(localStorage.getItem(key) || '[]');
  imageNotes = JSON.parse(localStorage.getItem(imageNotesKey) || '{}');
  const stored = notes[active];
  document.querySelectorAll('[data-answer]').forEach((field, i) => {
    const value = Array.isArray(stored) ? stored[i] || '' : i === 0 && typeof stored === 'string' ? stored : '';
    if (field.value !== value) field.value = value;
  });
  updateWritingMetrics();
  renderWords();
  if ($('imageAnswer')) {
    const value = imageNotes[imageBank[chosenImage].id] || '';
    if ($('imageAnswer').value !== value) $('imageAnswer').value = value;
    refreshImageText();
  }
});
